package io.forgeloop.control.application;
import io.forgeloop.control.domain.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import org.junit.jupiter.api.Test;
class FeatureRunServiceTest { FeatureRunRepository runs=mock(FeatureRunRepository.class); DeliveryTaskRepository tasks=mock(DeliveryTaskRepository.class); FeatureRunService service=new FeatureRunService(runs,tasks); @Test void submissionBuildsBoundedRun(){when(runs.save(any(FeatureRun.class))).thenAnswer(call->call.getArgument(0));FeatureRun run=service.submit(new FeatureSubmission("acme/support","issue-142","Assignment","- Admin can assign\n- Cross org is denied",25));assertEquals(4,run.getTasks().size());assertEquals(7,run.getGates().size());assertEquals(2,run.getCriteria().size());verify(runs).save(run);}@Test void invalidRepositoryIsRejected(){assertThrows(IllegalArgumentException.class,()->new FeatureSubmission("not a repo","i","t","spec",10));} }
